const analyticsUserOptions = `-- name: AnalyticsUserOptions :many
SELECT u.id, u.email
FROM users u
ORDER BY u.email, u.id
LIMIT 201
`

type AnalyticsUserOptionsRow struct {
	ID    uuid.UUID `json:"id"`
	Email string    `json:"email"`
}

func (q *Queries) AnalyticsUserOptions(ctx context.Context) ([]AnalyticsUserOptionsRow, error) {
	rows, err := q.db.Query(ctx, analyticsUserOptions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AnalyticsUserOptionsRow{}
	for rows.Next() {
		var i AnalyticsUserOptionsRow
		if err := rows.Scan(&i.ID, &i.Email); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
